def _prepare_damage(scenario: dict):
    from .catalog import operator_attributes
    scenario=dict(scenario)
    profile=catalog()['operators'][scenario['operator']]
    skill=scenario.get('skill');rank=scenario.get('skill_rank',10)
    if not isinstance(skill,int) or isinstance(skill,bool) or not 1<=skill<=len(profile['skills']):
        raise ValueError('请选择该干员的有效技能。')
    if not isinstance(rank,int) or isinstance(rank,bool) or not 1<=rank<=10:
        raise ValueError('技能等级需要为1–10的整数。')
    attributes=operator_attributes(scenario['operator'],scenario.get('elite',2),scenario.get('level'),
                                   scenario.get('trust',100),scenario.get('potential',1),
                                   scenario.get('module_id'),scenario.get('module_level',0))
    scenario.setdefault('base_attack',attributes['attack'])
    elite=scenario.get('elite',2)
    if profile['skills'][skill-1].get('unlock_elite',skill-1)>elite or (elite<2 and rank>7):
        raise ValueError('当前精英阶段尚未开放所选技能或专精。')
    if scenario['operator']=='silverash' and skill==3 and isinstance(scenario.get('preexisting_fragile'),str):
        raise ValueError('preexisting_fragile不接受字符串，请提供明确的布尔条件。')
    if scenario['operator']=='silverash' and skill==3 and isinstance(scenario.get('cooperative'),str):
        raise ValueError('cooperative不接受字符串，请提供明确的布尔条件。')
    # Preserve raw count types before either engine converts them to numbers.
    from .reporting import has_healing
    active_counts=[]
    if has_healing(scenario['operator'],skill):
        active_counts.append(('healing_targets','治疗目标数需要为 0–100 的整数。'))
    if scenario['operator']=='char_1037_amiya3' and skill==2:
        active_counts.append(('amiya_hit_targets','amiya_hit_targets需要1到100之间的整数。'))
    if scenario['operator']=='char_4087_ines':
        active_counts.append(('stolen_enemy_count','stolen_enemy_count需要范围内的有限非负整数。'))
    for field,error in active_counts:
        if isinstance(scenario.get(field),bool):raise ValueError(error)
    declared_counts={('mechanist',2):('shield_break_count',),
                     ('mechanist',3):('charge_count',),
                     ('silverash',2):('activation_count','deployment_stacks')}
    for field in declared_counts.get((scenario['operator'],skill),()):
        if isinstance(scenario.get(field),bool):
            raise ValueError(f'{field} 需要非负整数；部署触发叠层最多为 2。')
    from .relics import prepare
    from .run_modifiers import prepare_run
    scenario,run_resolution=prepare_run(scenario)
    scenario,resolution=prepare(scenario,profile)
    from .relic_attributes import prepare_attribute_runes
    scenario,attributes=prepare_attribute_runes(scenario,attributes)
    # Reuse the existing numeric-zero gates after validating the raw timing.
    timing=scenario.get('timing',{})
    if isinstance(timing,dict) and isinstance(timing.get('target_disappears_seconds'),str):
        from .timing import finite
        AttackTimeline(scenario)
        if finite(timing['target_disappears_seconds'],'target_disappears_seconds',3600)==0:
            scenario['timing']={**timing,'target_disappears_seconds':0}
    return scenario,attributes,resolution,run_resolution

def calculate_damage(scenario: dict) -> dict:
    from copy import deepcopy
    prepared=_prepare_damage(scenario)
    wines=[r for r in prepared[2]['rules'] if r['kind']=='periodic_sp']
    if len(wines)!=1 or all(w.get('clock')=='deployment' for w in wines):return _evaluate_damage(prepared)
    from .timing import frame_time
    from .reporting import build_report
    # Each possible 30-Hz phase, including immediate and full-period first tick.
    # Initial and post-block phases are independent marginal envelopes.
    phases=frame_time(wines[0]['interval'])+1
    keys=('initial_seconds','recharge_seconds','cycle_seconds','cycle_damage','cycle_healing','cycle_dps','cycle_hps')
    skill_bounds={key:_PhaseBounds() for key in keys}
    metric_bounds={}
    for phase in range(phases):
        # Copy together to preserve aliases between rules and resolution records.
        # Never share a finisher's mutations with another phase or request.
        result=_evaluate_damage(deepcopy(prepared),phase)
        for key,bounds in skill_bounds.items():bounds.include(result['estimate']['skill'][key])
        metrics={(b['id'],m['key']):m['value'] for b in result['report']['sections'] for m in b['metrics']}
        for key,value in metrics.items():
            if key not in metric_bounds:metric_bounds[key]=_PhaseBounds()
            metric_bounds[key].include(value)
    skill=result['estimate']['skill']
    for key in keys:
        bounds=skill_bounds[key]
        if not bounds.known:
            skill[key]=None
            continue
        lower,upper=bounds.lower,bounds.upper
        skill[key+'_range']={'lower':lower,'upper':upper}
        skill[key]=lower if abs(upper-lower)<1e-9 else None
    result['estimate']['notes'].append('酒类相位范围：逐一枚举30Hz参考帧的下一次回复相位（立即至一个完整间隔），逐事件合并攻击/受击技力；不换算平均每秒技力。')
    result['estimate']['notes'].append('范围假设：技能及额外阻回期间不接收、不积存酒类技力，阻回结束后的相位重新包络；初动和回转分别取范围，不表示同一条已测实战时间线。隐藏脚本、攻击模板与实战相位仍待校准。')
    result['relic_resolution']['phase_estimate']={'mode':'frame_envelope','phases':phases,
        'blocking':'discard_blocked_ticks','verified_phase':False,'verified_blocking_script':False}
    result['timing']['initial_seconds']=skill['initial_seconds']
    result['timing']['cycle_seconds']=skill['cycle_seconds']
    result['report']=build_report(scenario,result)
    # Metrics are ranged from complete event calculations, including non-monotone DPS.
    for block in result['report']['sections']:
        for row in block['metrics']:
            bounds=metric_bounds.get((block['id'],row['key']))
            if bounds and bounds.known and bounds.count==phases:
                lower,upper=bounds.lower,bounds.upper
                if abs(upper-lower)>1e-9:
                    row['value']=None;row['range']={'lower':lower,'upper':upper}
    return result

def value(value,label,maximum=None,integer=False):
        value=float(value)
        if not math.isfinite(value) or value<0 or (maximum is not None and value>maximum) or (integer and not value.is_integer()):
            raise ValueError(label+'需要范围内的有限非负'+('整数。' if integer else '数。'))
        return value

def option(self,key,default=0,maximum=None,integer=False):
        value=self.s.get(key,default)
        # Healing-target validation uses the public capability gate; inactive fields stay ignored.
        if integer and key!='healing_targets' and isinstance(value,bool):
            raise ValueError(key+'需要范围内的有限非负整数。')
        return self.value(value,key,maximum,integer)

def nonnegative(field,default):
        value=float(scenario.get(field,default))
        if not math.isfinite(value) or value<0:raise ValueError(f'{field} 需要有限非负数。')
        return value

def finite(value,label,maximum=108000):
    if isinstance(value,bool):raise ValueError(label+'不能是布尔值。')
    try:value=float(value)
    except (TypeError,ValueError):raise ValueError(label+'需要有限非负数。') from None
    if not math.isfinite(value) or not 0<=value<=maximum:raise ValueError(label+'需要范围内有限非负数。')
    return value

def __init__(self,scenario,normal=False,offset=0,target_scope='enemy'):
        if target_scope not in ('enemy','friendly'):raise ValueError('目标来源需要为enemy或friendly。')
        self.target_scope=target_scope
        self.s=scenario;self.normal=normal;self.offset=frame_time(offset)
        self.mode=scenario.get('timing_mode','frames')
        if self.mode not in ('frames','continuous'):raise ValueError('时序模式需要为frames或continuous。')
        self.options=scenario.get('timing',{})
        if not isinstance(self.options,dict):raise ValueError('时序情景需要是对象。')
        from .animation_reference import descriptor
        for normal_reference in (False,True):
            descriptor(scenario['operator'],scenario['skill'],self.options,normal=normal_reference)
        for key in ('windup_frames','recovery_frames','start_delay_frames','post_skill_lock_frames'):
            if key in self.options:finite(self.options[key],key)
        for key in ('sp_lockout_extra_seconds','projectile_travel_seconds','target_disappears_seconds'):
            if key in self.options:finite(self.options[key],key,3600)
        self.streams=[];self.notes=[];self.target_scope_notes=[]
        self.deployment_offset=0 if self.options.get('_deployment_initial') else frame_time(scenario.get('_deployment_skill_start_seconds',0))
        self.windows=self.ranges('target_windows')
        self.blocked=sorted(self.ranges('movement_windows')+self.ranges('interrupt_windows'))

def ranges(self,key):
        if key not in self.options:return []
        value=self.options[key]
        if not isinstance(value,list) or len(value)>100:raise ValueError(key+'需要最多100组秒数区间。')
        found=[]
        for pair in value:
            if not isinstance(pair,(list,tuple)) or len(pair)!=2:raise ValueError(key+'每组需要开始和结束秒数。')
            start,end=map(frame_time,pair)
            if end<=start:raise ValueError(key+'结束时间必须晚于开始时间。')
            found.append((start,end))
        return sorted(found)

def operator_attributes(operator, elite=2, level=None, trust=100, potential=1,module_id=None,module_level=0):
    profile = operator_profiles()[operator]
    if not isinstance(elite,int) or isinstance(elite,bool) or not 0<=elite<len(profile['phases']):
        raise ValueError('精英阶段需要为 0、1 或 2。')
    phase = profile['phases'][elite]
    level = phase['max_level'] if level is None else level
    if not isinstance(level,int) or isinstance(level,bool) or not 1 <= level <= phase['max_level'] or not math.isfinite(trust) or not 0 <= trust <= 100:
        raise ValueError('等级或信赖超出范围（信赖按加成进度 0–100%）。')
    if not isinstance(potential,int) or isinstance(potential,bool) or not 1<=potential<=6:
        raise ValueError('潜能需要为 1–6。')
    first, last = phase['frames'][0], phase['frames'][-1]
    fraction = (level - first['level']) / (last['level'] - first['level']) if last['level'] != first['level'] else 0
    stats={field:first[field]+fraction*(last[field]-first[field]) for field in last if field!='level'}
    for field in ('hp','attack','defense'):
        stats[field]=math.floor(stats[field]+.5)+math.floor(profile['trust_stats'][field]*trust/100+.5)
    mapping={'ATK':'attack','MAX_HP':'hp','DEF':'defense','MAGIC_RESISTANCE':'resistance',
             'RESPAWN_TIME':'redeploy_seconds','ATTACK_SPEED':'attack_speed','BLOCK_CNT':'block_count','COST':'deployment_cost'}
    for modifiers in profile['potential_bonuses'][:potential-1]:
        for modifier in modifiers:
            field=mapping.get(modifier['attributeType'])
            if field and modifier['formulaItem']=='ADDITION':stats[field]+=modifier['value']
    if module_id:
        module=next((m for m in profile['modules'] if m['id']==module_id),None)
        if not module or not isinstance(module_level,int) or isinstance(module_level,bool) or not 1<=module_level<=len(module['levels']):
            raise ValueError('模组身份或等级尚无可用规则。')
        if elite>=module['unlock_elite'] and level>=module['unlock_level']:
            for attr,value in module['levels'][module_level-1]['attributes'].items():
                field={'atk':'attack','def':'defense','max_hp':'hp','magic_resistance':'resistance','attack_speed':'attack_speed',
                       'respawn_time':'redeploy_seconds'}.get(attr)
                if field:stats[field]+=value
    return stats

def context_value(effect,scenario):
    condition=effect.get('condition')
    if not condition:return 1
    context=scenario.get('relic_context',{})
    if not isinstance(context,dict):raise ValueError('藏品条件需要JSON对象。')
    if condition=='emergency_hire':
        kind=scenario.get('recruitment_kind')
        if type(kind) is not str or kind not in ('non_emergency','emergency_hire'):return None
        return int(kind=='emergency_hire')
    value=context.get(condition,scenario.get(condition) if condition=='current_hp_ratio' else None)
    if value is None:return None
    if isinstance(value,bool) or not isinstance(value,(int,float)) or not math.isfinite(value) or value<0:
        raise ValueError('藏品条件 '+condition+'需要有限非负数。')
    if effect.get('condition_type')=='flag':
        if value not in (0,1):raise ValueError('藏品条件 '+condition+'需要0（未生效）或1（生效）。')
        return value
    if effect.get('condition_type')=='ratio':
        if value>1:raise ValueError('藏品条件 '+condition+'需要0–1的生命比例。')
        return value
    if 'hp_curve_min' in effect:
        if value>1:raise ValueError('当前生命比例需要0–1。')
        return min(1,(1-value)/(1-effect['hp_curve_min']))
    if effect.get('condition_type')=='seconds':
        if value>3600:raise ValueError('藏品时间 '+condition+'需要0–3600秒。')
    elif not float(value).is_integer() or value>10000:raise ValueError('藏品计数 '+condition+'需要0–10000的整数。')
    if effect.get('predicate')=='positive':return int(value>0)
    if effect.get('predicate')=='equals_one':return int(value==1)
    if effect.get('predicate')=='at_least':return int(value>=effect['threshold'])
    if effect.get('predicate')=='less_than':return int(value<effect['threshold'])
    if effect.get('divisor'):value=math.floor(value/effect['divisor'])
    return min(value,effect['maximum']) if 'maximum' in effect else value

def apply_attribute_runes(attributes, effects):
    """Return an independent snapshot; never fold runes into talent multipliers."""
    attributes = dict(attributes)
    for field in FIELDS.values():
        rules = [e for e in effects if is_attribute_rune(e) and FIELDS[e['kind']] == field]
        if not rules:
            continue
        # The native rune accumulator is FP/Q32. AttributesData's HP/ATK/DEF
        # are ObscuredInt: FP -> float32 -> ties-to-even happens before talents.
        # Reuse the previously sealed pure numeric conversion, not card costs.
        from .deployment import _fp, _fp_product, _single, _Q32
        def term(effect):
            if effect.get('native_count_scale') == 'float32_before_fp':
                return _fp(_single(_single(effect['native_rune_base']) * _single(effect['native_rune_factor'])))
            return _fp(effect['value'])
        addition = sum(term(e) for e in rules if e['formula_item'] == 'ADDITION')
        multiplier = _Q32 + sum(term(e) for e in rules if e['formula_item'] == 'MULTIPLIER')
        value = _fp_product(_fp(attributes[field]) + addition, multiplier)
        for effect in rules:
            if effect['formula_item'] == 'FINAL_SCALER':
                factor = _fp(effect['value'])
                if factor < 0:
                    factor += _Q32
                value = _fp_product(value, factor)
        value = max(0, _single(_single(value) / _Q32))
        attributes[field] = round(value) if field in ('hp', 'attack', 'defense', 'redeploy_seconds') else value
        if field == 'resistance':
            attributes[field] = min(100, attributes[field])
    if 'attack_speed' in attributes:
        from .attribute_limits import attack_speed_attribute
        attributes['attack_speed'] = attack_speed_attribute(attributes['attack_speed'])
    return attributes

def _single(value):
    if isinstance(value,bool) or not isinstance(value,(int,float)) or not math.isfinite(value):
        raise ValueError('费用计算参数需要有限数值。')
    try:return struct.unpack('<f',struct.pack('<f',value))[0]
    except (OverflowError,struct.error) as exc:raise ValueError('费用计算参数超出原生数值范围。') from exc

def _fp(value):
    scaled=_single(_single(value)*_Q32)
    if not math.isfinite(scaled) or not -(1<<63)<=scaled<(1<<63):
        raise ValueError('费用计算参数超出原生FP范围。')
    return int(scaled)

def resolve_enemy(scenario,resolution):
    target=scenario.get('target_enemy')
    if not target:
        if scenario.get('operator')=='char_1015_aglna2' and 'enemy_weight' in scenario:
            weight=scenario['enemy_weight']
            if (not isinstance(weight,(int,float)) or isinstance(weight,bool)
                    or not math.isfinite(weight) or not 0<=weight<=100 or weight!=int(weight)):
                raise ValueError('手动敌人重量必须是0到100之间的整数。')
            scenario['enemy_weight']=int(weight)
        else:scenario.pop('enemy_weight',None)
        return
    # Selected identity overrides the separate manual operator reference.
    scenario.pop('enemy_weight',None)
    if not isinstance(target,dict):raise ValueError('目标敌人需要关卡、敌人ID及引用等级。')
    sid=target.get('stage_id');stage=catalog()['stages'].get(sid);preview=stage_previews().get(sid)
    if not stage or not preview:raise ValueError('目标关卡没有固定敌人档案。')
    candidates=[e for e in preview['possible_enemies'] if e['id']==target.get('enemy_id') and e['level']==target.get('level')]
    if len(candidates)!=1:raise ValueError('目标敌人身份/等级必须与关卡引用唯一匹配。')
    record=candidates[0];stats=dict(record['reference_stats'])
    for key in ('maxHp','atk','def','magicResistance'):
        if not isinstance(stats.get(key),(int,float)) or not math.isfinite(stats[key]) or stats[key]<0:
            raise ValueError('目标敌人属性不完整。')
    enemy={**target,'name':record['name'],'stage_name':stage['name'],'stage_difficulty':stage['difficulty'],
        'level_type':record['level_type'],'reference_stats':dict(stats),'stats':stats,'steps':[],
        'damage_factor':1,'pending':[],'source':config_data()['source_url']}
    resolution['enemy']=enemy
    def multiply(label,values):
        for key,value in values.items():stats[key]*=value
        enemy['steps'].append({'label':label,'factors':values})
    for rune in preview['runes']:
        if rune['difficultyMask'] not in (stage['difficulty'],'ALL'):continue
        if rune['key']=='enemy_attribute_mul':
            if rune['professionMask']!=1023 or rune['buildableMask']!='ALL':
                enemy['pending'].append('关卡属性修正的目标范围尚未覆盖。');continue
            selectors=[b for b in rune['blackboard'] if b['key']=='enemy']
            if selectors:
                selector=selectors[0].get('valueStr') if len(selectors)==1 else None
                known_ids={e['id'] for e in preview['possible_enemies']}
                if not isinstance(selector,str) or selector not in known_ids:
                    enemy['pending'].append('关卡属性修正的敌人选择器尚未覆盖。');continue
                if selector!=record['id']:continue
            keys={'atk':'atk','def':'def','max_hp':'maxHp','magic_resistance':'magicResistance'}
            values={keys[b['key']]:b['value'] for b in rune['blackboard'] if b['key'] in keys}
            if len(values)!=len(rune['blackboard'])-len(selectors):enemy['pending'].append('关卡存在未覆盖的属性修正字段。')
            multiply('关卡 '+stage['difficulty'],values)
        elif rune['key']!='level_hidden_group_enable':
            enemy['pending'].append('关卡脚本修正待核验：'+rune['key'])
    if preview['global_buffs']:enemy['pending'].append('关卡全局脚本效果尚未逐项计算。')
    difficulty=resolution.get('difficulty')
    if difficulty:
        grade=difficulty['value']
        rules=difficulty_rules()
        low=rules['exclusive_low_grades'].get(str(grade))
        if low:
            multiply('当前低难度独立减益（不累计）',low)
            enemy['steps'][-1]['evidence']={k:rules[k] for k in ('source_url','verification','source_note')}
        if grade>=5:multiply('保密等级5+生命',{'maxHp':1.3})
        if grade>=8 and record['level_type'] in ('ELITE','BOSS'):multiply('保密等级8+精英/领袖攻击',{'atk':1.15})
        if grade>=11 and record['level_type']=='BOSS':
            enemy['damage_factor']=.8
            enemy['steps'].append({'label':'保密等级11+领袖受伤降低20%','damage_factor':.8})
        for rule in rules['enemy_thresholds']:
            if grade>=rule['grade'] and record['id']==rule['enemy_id']:
                multiply('保密等级'+str(rule['grade'])+'+专属属性',rule['factors'])
                enemy['steps'][-1]['evidence']={k:rules[k] for k in ('source_url','verification','source_note')}
                enemy['pending'].append(rule['pending'])
        rate=config_data()['difficulties'][str(grade)]['bossValue']/100
        zone=(scenario.get('run_config') or {}).get('zone')
        main=(zone or {}).get('main_zone_index')
        if zone and zone.get('id') in config_data()['zones'] and zone['id'].split('_')[1].isdigit():
            # zone_4 and zone_4_1 are the same main-region depth.
            main=int(zone['id'].split('_')[1])
        if rate and isinstance(main,int) and not isinstance(main,bool) and main in range(1,7):multiply('区域增长（主区域含第1层，黑潭不新增层数）',{'maxHp':(1+rate)**main,'atk':(1+rate)**main})
        elif rate:enemy['pending'].append('主区域深度尚未确认，未套用区域增长。')
    else:enemy['pending'].append('本局保密等级尚未确认，未套用难度修正。')
    if record['level_type'] not in ('NORMAL','ELITE','BOSS'):enemy['pending'].append('敌人类别未确认。')
    if record['id']=='enemy_2148_shorbb':
        rule=difficulty_rules()['orb_active'];mode=target.get('orb_mode','unknown')
        if mode in rule['modes']:
            factor=rule['modes'][mode]
            enemy['type_factors']={'physical':factor,'magic':factor}
            scenario['_enemy_type_factors']=enemy['type_factors']
            enemy['steps'].append({'label':'源阶方全程行动模式；所有伤害来源均'+('在目标占据列内' if mode=='active_same_column' else '在目标占据列外'),
                'type_factors':enemy['type_factors'],'evidence':{k:rule[k] for k in ('source_url','verification','source_note')}})
            resolution['notes'].append('源阶方使用明确选择的固定行动模式与统一来源列情景；未自动读取站位，不模拟激活、无敌、模式切换或混合来源列。')
        elif mode=='unknown':
            enemy['pending'].append('源阶方阶段和来源列未确认；当前数值仅为未套用自身减伤的参考，不是实际承伤估计。')
        else:raise ValueError('源阶方行动情景无效。')
    # Identity-derived state wins over stale manual relic or operator options.
    scenario['enemy_defense']=stats['def'];scenario['enemy_resistance']=stats['magicResistance']
    weight=stats.get('massLevel')
    if isinstance(weight,(int,float)) and not isinstance(weight,bool) and math.isfinite(weight):
        scenario['enemy_weight']=weight
    elif scenario.get('operator')=='char_1015_aglna2':
        raise ValueError('固定敌人重量档案缺失，无法选择重量天赋分支。')
    scenario['enemy_is_boss']=record['level_type']=='BOSS';scenario['enemy_level_type']=record['level_type']
    scenario['_run_damage_factor']=enemy['damage_factor']
    resolution['pending'].extend(enemy['pending'])
    resolution['notes'].append('敌人候选不保证出场；当前以持续存活目标计算，未模拟敌人自身技能、阶段、阻挡/环境变化和实际死亡时刻。')
